const icons = Object.keys(iconPaths);
export const neighborhoods = data.neighborhoods.map((neighborhood) => ({
  ...neighborhood,
  icon: icons[(neighborhood.position.x * data.gridHeight + neighborhood.position.y) % icons.length],
}));
